mapper.sql:
WHERE is_deleted = 0

    AND category = #{category}


    AND region = #{region}


    AND is_active = #{isActive}


    AND (material_code LIKE CONCAT('%', #{keyword}, '%')
         OR material_name LIKE CONCAT('%', #{keyword}, '%')
         OR project_model LIKE CONCAT('%', #{keyword}, '%')
         OR spec_model LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT * FROM material

ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}
